onLoad:
/* ---- 新玩法插件的公用小工具（每个插件都带一份，谁先加载谁建好，后面的直接用） ---- */
if (!window.GYX) (function () {
    const X = {};
    // 🔋 插件体检 / 省电：记下每个插件开的定时器（靠每个插件末尾的 //# sourceURL=gyx-plugin/名字.js 认出是谁开的），省电模式下让它们跑慢一点
    try {
