    let wTimer = null;
    X.widget = (k, def, fid) => { WQ.push([k, def, fid]); if (wFlush() || wTimer) return; let n = 0; wTimer = setInterval(() => { if (wFlush() || ++n > 120) { clearInterval(wTimer); wTimer = null; } }, 500); };
