try { new Function('X', 'applyMacros', "/* ⏰🌙 叫醒与哄睡：TA 按你定的时间叫你起床（赖床会被一遍遍叫）；睡前 TA 给你讲故事，配着雨声 / 白噪音，讲完慢慢变小声 */\nif (window.__gyxWake) return; window.__gyxWake = 1;\nX.feat('gyxWake', { n: '⏰ 叫醒与哄睡', desc: 'TA 按时叫你起床（赖床会一遍遍叫）；睡前讲故事、配雨声白噪音' });\nconst S = X.store('wake');\nlet D = { alarms: [], sleep: { noise: 'rain', min: 30, vol: .35, kind: 'fairy' }, stories: [] };   // alarm {id, at:'07:30', days:[1..7] | [], on, who, last}\nlet RING = null, NOISE = null;\nasync function wakeLine(c, n) {\n    if (X.bailu()) return X.cards(['叫醒', '早安', '聊天'], c, 1)[0] || ['起床啦，太阳晒屁股了。', '再不起我就要进来掀被子了。', '起来吧，我陪你。'][Math.min(2, n)];\n    const t = await X.ask(`${X.who(c)}\\n现在是早上 ${new Date().toTimeString().slice(0, 5)}，你在叫她起床，${n ? `这是第 ${n + 1} 次叫了，她还在赖床` : '她的闹钟刚响'}。说一句叫她起床的话（口语，一两句，${n ? '越叫越急 / 越无奈 / 越想笑，按你的性格' : '温柔一点'}），不要动作描写。只输出这句话。`);\n    return t ? X.plain(t) : '起床啦。';\n}\nasync function ring(al) {\n    if (RING) return; const c = X.char(al.who) || X.cur(); if (!c) return;\n    RING = { al, c, n: 0 };\n    const ov = document.createElement('div'); ov.id = 'gyxWkOv';\n    let av = ''; try { av = getAvatarHTML(c, 120); } catch (e) {}\n    ov.innerHTML = `<div class=\"wk-bg\"></div><div class=\"wk-c\"><div class=\"wk-t\">${new Date().toTimeString().slice(0, 5)}</div><div class=\"wk-av\">${av}</div><div class=\"wk-n\">${X.esc(X.name(c))}</div><div class=\"wk-s\" id=\"gyxWkS\">……</div>\n        <div class=\"wk-bt\"><button onclick=\"gyxWakeSnooze()\">再睡 5 分钟</button><button class=\"up\" onclick=\"gyxWakeUp()\">起来了</button></div></div>`;\n    document.body.appendChild(ov);\n    const say = async () => { if (!RING) return; const t = await wakeLine(c, RING.n); const e = document.getElementById('gyxWkS'); if (e) e.textContent = t; beep(); X.speak(c, t); };\n    await say();\n    RING.iv = setInterval(() => { if (!RING) return; RING.n++; say(); }, 45000);\n}\nfunction beep() { try { const a = new (window.AudioContext || window.webkitAudioContext)(); [0, .25, .5].forEach(t => { const o = a.createOscillator(), g = a.createGain(); o.frequency.value = 988; o.connect(g); g.connect(a.destination); g.gain.setValueAtTime(.001, a.currentTime + t); g.gain.exponentialRampToValueAtTime(.15, a.currentTime + t + .03); g.gain.exponentialRampToValueAtTime(.001, a.currentTime + t + .2); o.start(a.currentTime + t); o.stop(a.currentTime + t + .22); }); } catch (e) {} }\nfunction stopRing() { if (!RING) return null; clearInterval(RING.iv); const r = RING; RING = null; X.stopSpeak(); const o = document.getElementById('gyxWkOv'); if (o) o.remove(); return r; }\nwindow.gyxWakeUp = async () => { const r = stopRing(); if (!r) return; X.reach(r.c, `你刚把她叫起来了（叫了 ${r.n + 1} 次），说声早安，问问她今天的安排`); };\nwindow.gyxWakeSnooze = () => { const r = stopRing(); if (!r) return; X.toast('😴 再睡 5 分钟', X.name(r.c) + ' 5 分钟后再来叫你'); setTimeout(() => ring(r.al), 5 * 60000); };\nwindow.gyxWakeTest = id => ring(D.alarms.find(a => a.id === id) || { who: '' });\nasync function tick() { if (!X.on('gyxWake')) return;\n    const now = new Date(), hm = now.toTimeString().slice(0, 5), wd = now.getDay() || 7;\n    for (const al of D.alarms) { if (!al.on || al.at !== hm || al.last === X.day() + hm) continue; if (al.days && al.days.length && !al.days.includes(wd)) continue; al.last = X.day() + hm; await S.set('d', D); ring(al); if (!al.days || !al.days.length) { al.on = false; await S.set('d', D); } }\n}\n/* ---------------- 哄睡：白噪音 + 睡前故事 ---------------- */\nfunction noise(kind, vol) {\n    stopNoise(); try {\n        const a = new (window.AudioContext || window.webkitAudioContext)(), len = a.sampleRate * 4, b = a.createBuffer(2, len, a.sampleRate);\n        for (let ch = 0; ch < 2; ch++) { const d = b.getChannelData(ch); let last = 0; for (let i = 0; i < len; i++) { const w = Math.random() * 2 - 1; if (kind === 'brown' || kind === 'fire') { last = (last + .02 * w) / 1.02; d[i] = last * 3.5; } else if (kind === 'rain') { last = .96 * last + .04 * w; d[i] = w * .35 + last * .8 + (Math.random() < .0008 ? (Math.random() - .5) * 1.5 : 0); } else if (kind === 'wave') { d[i] = w * .5 * (0.5 + 0.5 * Math.sin(i / len * Math.PI * 2)); } else d[i] = w * .4; } }\n        const src = a.createBufferSource(); src.buffer = b; src.loop = true;\n        const f = a.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = { rain: 4200, brown: 700, wave: 1100, white: 9000, fire: 500 }[kind] || 3000;\n        const g = a.createGain(); g.gain.value = vol; src.connect(f); f.connect(g); g.connect(a.destination); src.start();\n        if (kind === 'fire') { const iv = setInterval(() => { if (!NOISE) return clearInterval(iv); if (Math.random() < .5) { const o = a.createBufferSource(), bb = a.createBuffer(1, a.sampleRate * .03, a.sampleRate), dd = bb.getChannelData(0); for (let i = 0; i < dd.length; i++) dd[i] = (Math.random() * 2 - 1) * (1 - i / dd.length); o.buffer = bb; const gg = a.createGain(); gg.gain.value = vol * .6; o.connect(gg); gg.connect(a.destination); o.start(); } }, 180); }\n        NOISE = { a, g, src };\n    } catch (e) {}\n}\nfunction stopNoise() { if (!NOISE) return; try { NOISE.src.stop(); NOISE.a.close(); } catch (e) {} NOISE = null; }\nwindow.gyxSleepStop = () => { stopNoise(); X.stopSpeak(); if (window.__gyxSleepT) clearTimeout(window.__gyxSleepT); const b = document.getElementById('gyxSlNow'); if (b) b.textContent = ''; };\n// 睡前故事：选个讲法——童话 / 把我们俩写进去 / 接着昨天的往下讲（连载）/ 平平淡淡的小日常 / 你点题；讲过的都收进故事本\nconst SK = [['fairy', '🧚 童话'], ['us', '💞 我们俩'], ['serial', '📖 接着昨天讲'], ['daily', '☕ 小日常'], ['ask', '✍️ 我点题']];\nasync function story(c) {\n    const k = D.sleep.kind || 'fairy', topic = ((document.getElementById('gyxSlTopic') || {}).value || '').trim(), last = (D.stories || []).find(x => x.cid === String(c.id));\n    let t;\n    if (X.bailu()) t = X.cards(['故事', '晚安', '聊天'], c, 5).join('。') || '从前有一只小兔子，它每天晚上都要数星星才能睡着……晚安。';\n    else {\n        const how = { fairy: '编一个温柔的童话', us: '把你们俩写进一个温柔的小故事里', serial: last ? `接着你上次讲的故事往下讲（上次讲到：${last.text.slice(-300)}）` : '开一个可以连着讲好几晚的故事的第一章', daily: '讲一段平平淡淡、很安心的小日常故事', ask: `按她点的题目讲：「${topic || '随便'}」` }[k];\n        t = await X.ask(`${X.who(c)}\n她要睡了，你给她讲一个睡前故事哄她睡觉：${how}。温柔、慢、没有刺激的情节；讲到后面越来越轻，最后跟她说晚安。400~800 字，像你在她耳边慢慢讲。只输出故事。`);\n    }\n    t = t || '从前有一只小兔子……晚安。';\n    D.stories = D.stories || []; D.stories.unshift({ at: Date.now(), cid: String(c.id), kind: k, topic, text: t }); await S.set('d', D);\n    return t;\n}\nwindow.gyxSleepKind = k => { D.sleep.kind = k; S.set('d', D); window.gyxWakeOpen(); };\nwindow.gyxSleepRead = i => { const x = (D.stories || [])[i]; const b = document.getElementById('gyxSlNow'); if (x && b) b.innerHTML = `<div class=\"gyx-hand sl-story\">${X.esc(x.text).replace(/\\n/g, '<br>')}</div>`; };\nwindow.gyxSleepStart = async function () {\n    const c = X.char(window.GYX_SL_WHO) || X.cur(); if (!c) return;\n    const b = document.getElementById('gyxSlNow'); if (b) b.textContent = 'TA 在想讲什么……';\n    noise(D.sleep.noise, D.sleep.vol);\n    const t = await story(c); if (b) b.innerHTML = `<div class=\"gyx-hand sl-story\">${X.esc(t).replace(/\\n/g, '<br>')}</div>`;\n    const parts = t.split(/(?<=[。！？…\\n])/).filter(s => s.trim());\n    (async () => { for (const p of parts) { if (!NOISE) break; await new Promise(res => { X.speak(c, p, res).then(r => { if (!r) res(); }); setTimeout(res, 8000 + p.length * 350); }); } })();\n    // 定时：慢慢变小声直到停\n    const end = Date.now() + D.sleep.min * 60000;\n    const fade = () => { if (!NOISE) return; const left = end - Date.now(); if (left <= 0) return window.gyxSleepStop(); if (left < 120000) NOISE.g.gain.value = D.sleep.vol * left / 120000; window.__gyxSleepT = setTimeout(fade, 2000); };\n    fade();\n    return t;\n};\nwindow.gyxWakeOpen = function () {\n    window.GYX_SL_WHO = window.GYX_SL_WHO || String((X.cur() || {}).id || '');\n    const cs = X.chars(), W = ['一', '二', '三', '四', '五', '六', '日'];\n    X.panel('gyxWkSet', '⏰ 叫醒与哄睡', `<div class=\"gyx-tip\">⏰ 叫醒：到点 TA 来叫你（谷雨开着才能叫；接了「TA 的声音」就是 TA 的声音）。赖床点「再睡 5 分钟」，TA 会越叫越急。</div>\n        ${D.alarms.map(a => `<div class=\"wk-al\"><input type=\"time\" class=\"gyx-who\" value=\"${a.at}\" onchange=\"gyxWakeEdit('${a.id}','at',this.value)\"><select class=\"gyx-who\" onchange=\"gyxWakeEdit('${a.id}','who',this.value)\">${cs.map(c => `<option value=\"${X.esc(c.id)}\"${String(c.id) === String(a.who) ? ' selected' : ''}>${X.esc(X.name(c))}</option>`).join('')}</select>\n            <span>${W.map((w, i) => `<i class=\"${(a.days || []).includes(i + 1) ? 'on' : ''}\" onclick=\"gyxWakeDay('${a.id}',${i + 1})\">${w}</i>`).join('')}</span><label><input type=\"checkbox\" ${a.on ? 'checked' : ''} onchange=\"gyxWakeEdit('${a.id}','on',this.checked)\">开</label><b onclick=\"gyxWakeTest('${a.id}')\">试</b><b onclick=\"gyxWakeDel('${a.id}')\">删</b></div>`).join('')}\n        <div class=\"gyx-row\"><button class=\"gyx-btn lite\" onclick=\"gyxWakeAdd()\">＋ 加一个闹钟</button><span class=\"gyx-tip\">不选星期＝只响一次</span></div>\n        <hr style=\"border:none;border-top:1px solid #eee\">\n        <div class=\"gyx-tip\">🌙 哄睡：TA 讲睡前故事，配着白噪音，到时间慢慢变小声。</div>\n        <div class=\"gyx-row\">${X.whoSel(window.GYX_SL_WHO, 'gyxSleepWho')} ${[['rain', '雨声'], ['wave', '海浪'], ['brown', '低沉的风'], ['fire', '壁炉'], ['white', '白噪音']].map(([k, n]) => `<span class=\"gyx-chip ${D.sleep.noise === k ? 'on' : ''}\" onclick=\"gyxSleepCfg('noise','${k}')\">${n}</span>`).join('')}</div>\n        <div class=\"gyx-row\">放 <input class=\"gyx-who\" type=\"number\" min=\"1\" value=\"${D.sleep.min}\" style=\"width:70px\" onchange=\"gyxSleepCfg('min',+this.value)\"> 分钟 · 音量 <input type=\"range\" min=\"0\" max=\"1\" step=\".05\" value=\"${D.sleep.vol}\" oninput=\"gyxSleepCfg('vol',+this.value)\"></div>\n        <div class=\"gyx-row\">${SK.map(([k, n]) => `<span class=\"gyx-chip ${(D.sleep.kind || 'fairy') === k ? 'on' : ''}\" onclick=\"gyxSleepKind('${k}')\">${n}</span>`).join('')}</div>${D.sleep.kind === 'ask' ? '<input id=\"gyxSlTopic\" class=\"gyx-in\" placeholder=\"想听什么故事\">' : ''}\n        <div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"gyxSleepStart()\">开始哄睡</button><button class=\"gyx-btn lite\" onclick=\"gyxSleepStop()\">停</button></div><div id=\"gyxSlNow\"></div>${(D.stories || []).length ? `<details><summary class=\"gyx-tip\">📚 故事本（${D.stories.length} 个）</summary>${D.stories.slice(0, 60).map((x, i) => `<div class=\"gyx-tip\" style=\"cursor:pointer\" onclick=\"gyxSleepRead(${i})\">${new Date(x.at).toLocaleDateString()} · ${X.esc(X.name(X.char(x.cid)))} · ${X.esc(x.text.slice(0, 26))}…</div>`).join('')}</details>` : ''}`);\n};\nwindow.gyxSleepWho = v => { window.GYX_SL_WHO = v; };\nwindow.gyxSleepCfg = (k, v) => { D.sleep[k] = v; S.set('d', D); if (k === 'vol' && NOISE) NOISE.g.gain.value = v; if (k === 'noise') { if (NOISE) noise(v, D.sleep.vol); window.gyxWakeOpen(); } };\nwindow.gyxWakeAdd = async () => { D.alarms.push({ id: 'al' + Date.now(), at: '07:30', days: [1, 2, 3, 4, 5], on: true, who: String((X.cur() || {}).id || '') }); await S.set('d', D); window.gyxWakeOpen(); };\nwindow.gyxWakeEdit = async (id, k, v) => { const a = D.alarms.find(x => x.id === id); if (a) { a[k] = v; await S.set('d', D); } };\nwindow.gyxWakeDay = async (id, d) => { const a = D.alarms.find(x => x.id === id); if (!a) return; a.days = a.days || []; const i = a.days.indexOf(d); if (i >= 0) a.days.splice(i, 1); else a.days.push(d); await S.set('d', D); window.gyxWakeOpen(); };\nwindow.gyxWakeDel = async id => { D.alarms = D.alarms.filter(x => x.id !== id); await S.set('d', D); window.gyxWakeOpen(); };\nwindow.gyxWakeData = () => D;\nX.action({ key: 'gyx_sleep', label: '睡前哄她睡觉（讲个睡前故事）', hint: '很晚了', need: c => { const h = new Date().getHours(); return (h >= 22 || h < 2) && D.story !== X.day() + c.id; }, run: async c => { D.story = X.day() + c.id; await S.set('d', D); const t = await story(c); X.say(c, '🌙 ' + t); return '给你讲了个睡前故事'; } }, 'gyxWake');\nX.css('gyxWkCss', `\n#gyxWkOv{position:fixed;inset:0;z-index:100003;display:flex;align-items:center;justify-content:center;color:#fff;font-family:-apple-system,\"PingFang SC\",sans-serif}\n#gyxWkOv .wk-bg{position:absolute;inset:0;background:linear-gradient(180deg,#ffb88c,#de6262 45%,#4b3869);animation:wkSun 6s ease-in-out infinite alternate}\n@keyframes wkSun{to{filter:hue-rotate(-15deg) brightness(1.08)}}\n#gyxWkOv .wk-c{position:relative;text-align:center;padding:20px}.wk-t{font-size:72px;font-weight:200;letter-spacing:2px}.wk-av{display:flex;justify-content:center;margin:18px 0 8px;animation:wkShake 1.2s infinite}.wk-av .avatar{box-shadow:0 0 0 6px rgba(255,255,255,.3),0 0 0 14px rgba(255,255,255,.12)}\n@keyframes wkShake{0%,100%{transform:rotate(0)}10%{transform:rotate(-8deg)}20%{transform:rotate(8deg)}30%{transform:rotate(-5deg)}40%{transform:rotate(0)}}\n.wk-n{font-size:20px}.wk-s{font-size:17px;margin:14px auto 28px;max-width:320px;line-height:1.6;min-height:3em}\n.wk-bt{display:flex;gap:14px;justify-content:center}.wk-bt button{padding:14px 22px;border-radius:999px;border:none;font-size:16px;background:rgba(255,255,255,.22);color:#fff;backdrop-filter:blur(10px);cursor:pointer;font-family:inherit}.wk-bt .up{background:#fff;color:#de6262}\n.wk-al{display:flex;gap:6px;align-items:center;flex-wrap:wrap;padding:8px 10px;border-radius:14px;background:#f7f7f9;margin:6px 0;font-size:13px}.wk-al span i{font-style:normal;display:inline-block;width:22px;height:22px;line-height:22px;text-align:center;border-radius:50%;cursor:pointer;color:#999}.wk-al span i.on{background:#1d1d1f;color:#fff}.wk-al b{color:#1d9bf0;cursor:pointer;font-weight:normal}\n.sl-story{font-size:18px;line-height:1.9;max-height:40vh;overflow:auto;padding:12px;border-radius:14px;background:#1f2238;color:#e6e3ff;margin-top:8px}\n`);\nX.today(() => { const W = ['日', '一', '二', '三', '四', '五', '六']; const rows = D.alarms.filter(a => a.on).map(a => ({ t: a.at, x: `${X.esc(X.name(X.char(a.who)))} 叫你起床${a.days && a.days.length ? '（周' + a.days.map(d => W[d % 7]).join('') + '）' : '（一次）'}`, go: 'gyxWakeOpen()' })); return { title: '⏰ 叫醒', rows }; }, 'gyxWake');\nX.mini({ id: 'gyxWake', icon: '⏰', title: '叫醒与哄睡', desc: 'TA 按时叫你起床（赖床会一遍遍叫）；睡前讲故事、配雨声白噪音', onOpen: () => window.gyxWakeOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.alarms = D.alarms || []; D.sleep = Object.assign({ noise: 'rain', min: 30, vol: .35 }, D.sleep || {}); setInterval(tick, 15000); })();\nX.widget('gyxWakeW', { n: '叫醒我', sizes: ['s', 'm'], tap: () => window.gyxWakeOpen(), r: w => { const L = D.alarms.filter(a => a.on).sort((a, b) => a.at < b.at ? -1 : 1); return X.gw(w, '⏰', '叫醒与哄睡', L.length ? [L[0].at, X.esc(X.name(X.char(L[0].who))) + ' 叫你起床', L.length > 1 ? '还有 ' + (L.length - 1) + ' 个' : ''] : ['设个闹钟', '让 TA 叫你起床']); } }, 'gyxWake');\nX.memArr({ k: 'gyxStory', ico: '📖', n: '讲过的睡前故事', d: '哄睡时 TA 讲的故事', arr: () => D.stories || [], text: x => x.text, field: 'text', save: () => S.set('d', D) }, 'gyxWake');\n\n//# sourceURL=gyx-plugin/叫醒与哄睡.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] ⏰🌙 叫醒与哄睡 出错：', e); }
/* ==== 🌙 熬夜管家 ==== */
try { new Function('X', 'applyMacros', "/* 🌙 熬夜管家：过了你定的睡觉时间还在玩，TA 会来催你——先温柔、再严肃、最后「我陪你一起躺下」；第二天早上还会说你；每周有一份熬夜小报告 */\nif (window.__gyxNight) return; window.__gyxNight = 1;\nX.feat('gyxNight', { n: '🌙 熬夜管家', desc: '过了睡觉时间还在玩，TA 会来催你睡觉' });\nconst S = X.store('night');\nlet D = { cfg: { bed: '00:30', who: '', gap: 20, strict: 2 }, log: {}, nag: {} };   // log[day]={last: 最晚还醒着的时间(分钟，跨零点算 24+)}\nlet lastAct = Date.now();\n['pointerdown', 'keydown', 'wheel', 'touchstart'].forEach(e => addEventListener(e, () => { lastAct = Date.now(); }, { passive: true, capture: true }));\nconst mins = hm => { const [h, m] = String(hm).split(':').map(Number); return h * 60 + (m || 0); };\n// 「夜里」的分钟数：凌晨算到 24 点以后（01:00 → 25*60）\nconst nightMin = d => { const m = d.getHours() * 60 + d.getMinutes(); return m < 12 * 60 ? m + 24 * 60 : m; };\nconst bedMin = () => { const b = mins(D.cfg.bed); return b < 12 * 60 ? b + 24 * 60 : b; };\nconst nightKey = d => { const x = new Date(d); if (x.getHours() < 12) x.setDate(x.getDate() - 1); return X.day(x); };\nfunction who() { return X.char(D.cfg.who) || X.cur(); }\nasync function nag(c, level, late) {\n    const lines = [['还不睡呀？', '已经很晚啦，放下手机好不好', '乖，该睡觉了'], ['我数到三，你放下手机', '再不睡我要生气了', '说好早睡的呢'], ['我陪你一起躺下，闭眼，不许偷看手机了', '好了，我把灯关了，晚安', '你不睡我也不睡了，陪你耗着']];\n    if (X.bailu()) { X.say(c, X.cards(['熬夜', '晚安'], c, 1)[0] || X.pick(lines[Math.min(2, level)])); return; }\n    const tone = ['温柔地提醒', '认真一点地催（有点生气但心疼）', '软下来，说要陪她一起躺下、哄她睡'][Math.min(2, level)];\n    await X.reach(c, `现在已经 ${new Date().toTimeString().slice(0, 5)} 了，比她说好的睡觉时间（${D.cfg.bed}）晚了 ${late} 分钟，她还在玩手机。这是今晚你第 ${level + 1} 次催她，${tone}`);\n}\nasync function tick() {\n    if (!X.on('gyxNight')) return;\n    const now = new Date(), nm = nightMin(now), k = nightKey(now);\n    const active = Date.now() - lastAct < 5 * 60000 && !document.hidden;\n    if (active && nm >= 21 * 60) { const L = D.log[k] = D.log[k] || {}; if (!L.last || nm > L.last) { L.last = nm; await S.set('d', D); } }\n    if (!active || nm < bedMin()) return;\n    const c = who(); if (!c) return; if (X.auto(c) && !X.on('gyxNight.auto')) return;\n    const N = D.nag[k] = D.nag[k] || { n: 0, at: 0 };\n    if (N.n >= Math.max(1, +D.cfg.strict + 1) || Date.now() - N.at < (+D.cfg.gap || 20) * 60000) return;\n    N.at = Date.now(); const lv = N.n++; await S.set('d', D);\n    await nag(c, lv, nm - bedMin());\n}\n// 早上：昨晚熬夜了，TA 说你两句\nasync function morning() {\n    if (!X.on('gyxNight')) return; const h = new Date().getHours(); if (h < 6 || h > 12) return;\n    const y = new Date(); y.setDate(y.getDate() - 1); const k = X.day(y), L = D.log[k];\n    if (!L || !L.last || L.last < bedMin() + 30 || L.said) return;\n    L.said = 1; await S.set('d', D); const c = who(); if (!c) return;\n    const t = `${String(Math.floor(L.last / 60) % 24).padStart(2, '0')}:${String(L.last % 60).padStart(2, '0')}`;\n    if (X.bailu()) X.say(c, X.cards(['熬夜', '早安'], c, 1)[0] || '昨晚又熬夜了吧？今天中午补个觉。');\n    else await X.reach(c, `她昨晚一直到 ${t} 才睡（说好 ${D.cfg.bed} 睡的）。早上见到她，按你的性格说说她（心疼、念叨、或者罚她今晚早睡）`);\n}\nfunction week() { const out = []; for (let i = 7; i >= 1; i--) { const d = new Date(); d.setDate(d.getDate() - i); const L = D.log[X.day(d)]; out.push({ d, last: L && L.last }); } return out; }\nconst fmt = m => m ? `${String(Math.floor(m / 60) % 24).padStart(2, '0')}:${String(m % 60).padStart(2, '0')}` : '—';\nwindow.gyxNightOpen = function () {\n    const W = week(), late = W.filter(x => x.last && x.last > bedMin()).length, bm = bedMin();\n    X.panel('gyxNtOv', '🌙 熬夜管家', `<div class=\"gyx-row\">谁来管你：<select class=\"gyx-who\" onchange=\"gyxNightCfg('who',this.value)\"><option value=\"\">最近聊天的人</option>${X.chars().map(c => `<option value=\"${X.esc(c.id)}\"${String(c.id) === String(D.cfg.who) ? ' selected' : ''}>${X.esc(X.name(c))}</option>`).join('')}</select></div>\n        <div class=\"gyx-row\">几点该睡：<input type=\"time\" class=\"gyx-who\" value=\"${D.cfg.bed}\" onchange=\"gyxNightCfg('bed',this.value)\"> · 每隔 <input class=\"gyx-who\" type=\"number\" min=\"1\" value=\"${D.cfg.gap}\" style=\"width:60px\" onchange=\"gyxNightCfg('gap',+this.value)\"> 分钟催一次 · 最多 <input class=\"gyx-who\" type=\"number\" min=\"0\" value=\"${+D.cfg.strict + 1}\" style=\"width:60px\" onchange=\"gyxNightCfg('strict',+this.value-1)\"> 次</div>\n        <div class=\"gyx-tip\">过了睡觉时间你还在谷雨里点来点去，TA 就会来催。第二天早上，如果你熬得很晚，TA 也会说你。</div>\n        <div class=\"nt-rep\"><b>这周 ${late} 天熬夜</b><div class=\"nt-bars\">${W.map(x => { const h = x.last ? Math.max(6, Math.min(100, (x.last - 21 * 60) / (8 * 60) * 100)) : 4; return `<div><i style=\"height:${h}%;background:${x.last && x.last > bm ? '#ff7a8a' : '#8fb8ff'}\"></i><span>${'日一二三四五六'[x.d.getDay()]}</span><em>${fmt(x.last)}</em></div>`; }).join('')}</div><div class=\"gyx-tip\">柱子越高睡得越晚；红色＝超过了你定的时间</div></div>`, 'dark');\n};\nwindow.gyxNightCfg = (k, v) => { D.cfg[k] = v; S.set('d', D); };\nwindow.gyxNightTest = async () => { const c = who(); await nag(c, 0, 30); };\nwindow.gyxNightData = () => D;\nX.action({ key: 'gyx_night', label: '催她早点睡（她还在熬夜）', hint: '已经过了她的睡觉时间', need: () => { const nm = nightMin(new Date()); return nm >= bedMin() && Date.now() - lastAct < 5 * 60000; }, run: async c => { await nag(c, 0, nightMin(new Date()) - bedMin()); return '催你去睡觉'; } }, 'gyxNight');\nX.ctx(() => { const nm = nightMin(new Date()); if (nm < bedMin()) return ''; return `【熬夜】现在已经过了她说好的睡觉时间（${D.cfg.bed}），她还没睡。你会惦记着让她早点去睡。`; }, 'gyxNight');\nX.today(() => { const y = new Date(); y.setDate(y.getDate() - 1); const L = D.log[X.day(y)]; const rows = [{ t: D.cfg.bed, x: '今晚该睡的时间', go: 'gyxNightOpen()' }]; if (L && L.last) rows.push({ t: fmt(L.last), x: L.last > bedMin() ? '<b>昨晚熬夜了</b>' : '昨晚按时睡了 👍', go: 'gyxNightOpen()' }); return { title: '🌙 睡觉', rows }; }, 'gyxNight');\nX.css('gyxNtCss', `#gyxNtOv .gyx-box{background:linear-gradient(170deg,#1d2140,#2d2350);color:#eef}#gyxNtOv .gyx-hd{background:rgba(29,33,64,.9)}#gyxNtOv .gyx-tip{color:#aab}#gyxNtOv .gyx-who{background:#2b2f55;color:#fff;border-color:#454a7a}\n.nt-rep{margin-top:12px;padding:14px;border-radius:18px;background:rgba(255,255,255,.06)}.nt-bars{display:flex;gap:8px;height:140px;align-items:flex-end;margin:10px 0}.nt-bars div{flex:1;display:flex;flex-direction:column;align-items:center;height:100%;justify-content:flex-end;font-size:11px}.nt-bars i{width:70%;border-radius:6px 6px 2px 2px}.nt-bars span{margin-top:4px}.nt-bars em{font-style:normal;color:#99a;font-size:10px}`);\nX.mini({ id: 'gyxNight', icon: '🌙', title: '熬夜管家', desc: '过了睡觉时间还在玩，TA 会来催你；还有每周熬夜报告', onOpen: () => window.gyxNightOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.cfg = Object.assign({ bed: '00:30', who: '', gap: 20, strict: 2 }, D.cfg || {}); D.log = D.log || {}; D.nag = D.nag || {}; setInterval(tick, 60000); setTimeout(morning, 20000); setInterval(morning, 30 * 60000); })();\nX.widget('gyxNightW', { n: '熬夜管家', sizes: ['s', 'm'], tap: () => window.gyxNightOpen(), r: w => { const y = new Date(); y.setDate(y.getDate() - 1); const L = D.log[X.day(y)]; return X.gw(w, '🌙', '熬夜管家', [D.cfg.bed + ' 该睡了', L && L.last ? '昨晚 ' + fmt(L.last) + (L.last > bedMin() ? ' 才睡' : ' 乖乖睡了') : '']); } }, 'gyxNight');\n\n//# sourceURL=gyx-plugin/熬夜管家.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : undefined); } catch (e) { console.error('[插件] 🌙 熬夜管家 出错：', e); }
/* ==== 🕯️ 睡前三件好事 ==== */
try { new Function('X', 'applyMacros', "/* 🕯️ 睡前三件好事：每晚睡前一个小仪式——你写下今天的三件好事（再小都算），和一件明天期待的事；TA 也写 TA 的，然后互相看。到点 TA 会来提醒，攒下来是一本只有好事的本子 */\nif (window.__gyxGood) return; window.__gyxGood = 1;\nX.feat('gyxGood', { n: '🕯️ 睡前三件好事', desc: '每晚写三件好事和一件明天期待的事，TA 也写，攒成好事本' });\nconst S = X.store('good');\nlet D = { days: {}, cfg: { hour: 22, remind: true }, told: {} };   // days[cid][day] = {me:[], meT:'', ta:[], taT:'', at, re}\nconst rec = (cid, d) => { const k = String(cid); D.days[k] = D.days[k] || {}; return (D.days[k][d] = D.days[k][d] || {}); };\nasync function taWrite(c, r) {\n    if (r.ta && r.ta.length) return r;\n    let j = X.bailu() ? null : X.json(await X.ask(`${X.who(c)}\\n睡前小仪式：写下你今天的三件好事（具体、小小的也行，可以和她有关），再写一件明天期待的事。\\n今天的聊天：\\n${X.recent(c, 16)}\\n只输出 JSON：{\"three\":[\"\",\"\",\"\"],\"tomorrow\":\"\"}`));\n    if (!j || !Array.isArray(j.three)) { const cs = X.cards(['日记', '情话', '聊天'], c, 4).map(t => X.plain(t).slice(0, 30)); j = { three: [cs[0] || '今天你回我消息很快', cs[1] || '晚饭挺好吃的', cs[2] || '现在能跟你说晚安'], tomorrow: cs[3] || '明天早上第一个跟你说早安' }; }\n    r.ta = j.three.slice(0, 3).map(t => X.plain(t)); r.taT = X.plain(j.tomorrow || ''); await S.set('d', D); return r;\n}\nwindow.gyxGoodSave = async (cid) => {\n    const c = X.char(cid) || X.cur(); const v = i => ((document.getElementById('gyxGd' + i) || {}).value || '').trim(); const me = [v(0), v(1), v(2)].filter(Boolean); if (!me.length) { X.toast('🕯️ 写一件就行', '再小的事都算'); return null; }\n    const r = rec(c.id, X.day()); r.me = me; r.meT = v('T'); r.at = Date.now(); await S.set('d', D); await taWrite(c, r);\n    r.re = X.plain((X.bailu() ? null : await X.ask(`${X.who(c)}\\n睡前你们交换了今天的好事。她写的：${r.me.join('；')}；明天期待：${r.meT || '（没写）'}。你写的：${r.ta.join('；')}。看完她的，说一句晚安前的话（温柔、可以回应她写的某一件）。`)) || X.pick(['今天也辛苦了。晚安，明天见。', '有好事就够了。晚安。', '你写的第一件，我也很开心。晚安。']));\n    await S.set('d', D); window.gyxGoodOpen(c.id); return r;\n};\nwindow.gyxGoodData = () => D;\nwindow.gyxGoodCfg = (k, v) => { D.cfg[k] = v; S.set('d', D); };\nconst streak = cid => { const all = D.days[String(cid)] || {}, d = new Date(); if (!(all[X.day(d)] || {}).me) d.setDate(d.getDate() - 1); let n = 0; while ((all[X.day(d)] || {}).me) { n++; d.setDate(d.getDate() - 1); } return n; };\nwindow.gyxGoodOpen = function (who, day) {\n    const c = X.char(who) || X.cur(); if (!c) return; const cid = String(c.id), all = D.days[cid] || {}, today = X.day(), r = (day ? all[day] : all[today]) || {}, ks = Object.keys(all).filter(k => all[k].me).sort().reverse(), show = day || today;\n    X.panel('gyxGdOv', '🕯️ 睡前三件好事', `<div class=\"gyx-row\">${X.whoSel(cid, 'gyxGoodOpen')}<span class=\"gyx-tip\">连续 ${streak(cid)} 晚 · 一共 ${ks.length} 晚</span></div>\n        <div class=\"gd-pg\"><em>${show}</em>${r.me ? `<div class=\"gd-two\"><div><b>你</b><ol>${r.me.map(t => `<li>${X.esc(t)}</li>`).join('')}</ol>${r.meT ? `<div class=\"gd-t\">明天期待：${X.esc(r.meT)}</div>` : ''}</div><div><b>${X.esc(X.name(c))}</b><ol>${(r.ta || []).map(t => `<li>${X.esc(t)}</li>`).join('')}</ol>${r.taT ? `<div class=\"gd-t\">明天期待：${X.esc(r.taT)}</div>` : ''}</div></div>${r.re ? `<div class=\"gd-re gyx-hand\">${X.esc(r.re)}</div>` : ''}`\n        : show === today ? `<div class=\"gyx-tip\">${X.v('今天有什么好事？再小都算。', '睡前想三件好事，会睡得好一点。', '写完我们交换着看。')}</div>${[0, 1, 2].map(i => `<input id=\"gyxGd${i}\" class=\"gyx-in gd-in\" placeholder=\"${['第一件好事', '第二件', '第三件'][i]}\">`).join('')}<input id=\"gyxGdT\" class=\"gyx-in gd-in\" placeholder=\"明天期待的一件事\"><div class=\"gyx-row\"><button class=\"gyx-btn\" onclick=\"this.disabled=true;this.textContent='交换中…';gyxGoodSave('${cid}')\">写好了，交换</button></div>` : '<div class=\"gyx-tip\">这天没写</div>'}</div>\n        ${day ? `<div class=\"gyx-row\"><button class=\"gyx-btn lite\" onclick=\"gyxGoodOpen('${cid}')\">回到今天</button></div>` : ''}\n        <div style=\"font-weight:700;margin:12px 0 4px\">好事本</div><div class=\"gd-cal\">${ks.slice(0, 60).map(k => `<span onclick=\"gyxGoodOpen('${cid}','${k}')\">${k.slice(5)}</span>`).join('') || '<span class=\"gyx-tip\">还是空的</span>'}</div>\n        <div class=\"gyx-row gyx-tip\"><label><input type=\"checkbox\" ${D.cfg.remind ? 'checked' : ''} onchange=\"gyxGoodCfg('remind',this.checked)\"> 每晚</label><input class=\"gyx-who\" type=\"number\" min=\"0\" max=\"23\" value=\"${D.cfg.hour}\" style=\"width:52px\" onchange=\"gyxGoodCfg('hour',+this.value)\"> 点 TA 来提醒</div>`);\n};\nasync function tick() {\n    if (!X.on('gyxGood') || !D.cfg.remind) return; const h = new Date().getHours(), d = X.day(); if (h !== +D.cfg.hour) return;\n    for (const c of X.chars().slice(0, 1).concat(X.cur() ? [X.cur()] : []).filter((v, i, a) => a.indexOf(v) === i)) { const k = String(c.id) + d; if (D.told[k] || (rec(c.id, d).me)) continue; D.told[k] = 1; await S.set('d', D); X.notify(c, `🕯️ ${X.esc(X.name(c))}：${X.v('睡前三件好事，写了吗？', '今天的好事是什么呀？', '来交换今天的三件好事')}`, '写完一起看', () => window.gyxGoodOpen(c.id)); }\n}\nX.ctx(id => { const r = (D.days[String(id)] || {})[X.day()]; if (r && r.me) return `【今晚你们交换了三件好事】她：${r.me.join('；')}${r.meT ? '；明天期待：' + r.meT : ''}。你：${(r.ta || []).join('；')}。`; const y = new Date(); y.setDate(y.getDate() - 1); const p = (D.days[String(id)] || {})[X.day(y)]; return p && p.meT ? `【她昨晚说今天期待】${p.meT}——可以问问她怎么样了。` : ''; }, 'gyxGood');\nX.action({ key: 'gyx_good', label: '睡前叫她一起写今天的三件好事', hint: '睡前小仪式', need: c => new Date().getHours() >= 20 && !(rec(c.id, X.day()).me),\n    run: async c => { await taWrite(c, rec(c.id, X.day())); return (await X.reach(c, '快睡了，你想和她交换今天的三件好事（「🕯️ 睡前三件好事」里，你已经写好了）。温柔地叫她去写')) ? '叫你一起写三件好事' : null; } }, 'gyxGood');\nX.today(() => { const c = X.cur(); if (!c) return null; const r = rec(c.id, X.day()); return { title: '🕯️ 睡前三件好事', rows: [{ t: r.me ? '已交换' : '今晚', x: r.me ? X.esc(r.me[0]) : '还没写', go: `gyxGoodOpen('${c.id}')` }] }; }, 'gyxGood');\nX.widget('gyxGoodW', { n: '三件好事', sizes: ['s', 'm'], tap: () => window.gyxGoodOpen(), r: w => { const c = X.cur(); if (!c) return X.gw(w, '🕯️', '三件好事', []); const r = rec(c.id, X.day()); return X.gw(w, '🕯️', '三件好事', [r.me ? '今晚写好了 ✓' : '今晚还没写', '连续 ' + streak(c.id) + ' 晚']); } }, 'gyxGood');\nX.mem({ k: 'gyxGood', ico: '🕯️', n: '睡前三件好事', d: '每晚的三件好事（你的｜TA 的）', items: c => { const all = D.days[String(c.id)] || {}; return Object.keys(all).filter(k => all[k].me).sort().reverse().map(k => Object.assign(all[k], { day: k })); }, text: x => x.me.join('；') + '｜' + (x.ta || []).join('；'), edit: (x, v) => { const [a, b] = v.split('｜'); x.me = a.split(/[；;]/).filter(Boolean); if (b != null) x.ta = b.split(/[；;]/).filter(Boolean); }, del: (c, i) => { const all = D.days[String(c.id)] || {}, ks = Object.keys(all).filter(k => all[k].me).sort().reverse(); delete all[ks[i]]; }, meta: x => x.day, save: () => S.set('d', D) }, 'gyxGood');\nX.css('gyxGdCss', `.gd-pg{border-radius:18px;padding:14px;background:linear-gradient(#2d2a4a,#463a63);color:#f6efe2;margin:8px 0}.gd-pg em{font-style:normal;font-size:12px;opacity:.7}.gd-pg .gyx-tip{color:#d9cfe9}.gd-in{background:rgba(255,255,255,.12)!important;border-color:rgba(255,255,255,.2)!important;color:#fff!important;margin-top:6px}.gd-two{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin-top:6px}.gd-two b{color:#ffd98a}.gd-two ol{margin:6px 0;padding-left:18px;font-size:14px;line-height:1.7}.gd-t{font-size:12.5px;color:#ffd98a}.gd-re{margin-top:10px;font-size:17px;text-align:center;color:#ffe8b8}.gd-cal{display:flex;flex-wrap:wrap;gap:6px}.gd-cal span{padding:4px 9px;border-radius:10px;background:#efeaf7;font-size:12.5px;cursor:pointer;color:#6a4f96}@media(max-width:480px){.gd-two{grid-template-columns:1fr}}`);\nX.mini({ id: 'gyxGood', icon: '🕯️', title: '睡前三件好事', desc: '每晚交换三件好事', cat: '陪伴', onOpen: () => window.gyxGoodOpen() });\n(async () => { D = Object.assign(D, await S.get('d', {})); D.days = D.days || {}; D.told = D.told || {}; D.cfg = Object.assign({ hour: 22, remind: true }, D.cfg || {}); setInterval(tick, 300000); setTimeout(tick, 30000); })();\n\n//# sourceURL=gyx-plugin/睡前三件好事.js")(X, typeof applyMacros !== 'undefined' ? applyMacros : un